const input = items[0]?.json || {};

return [
 {
   json: {
     ...input,
     final_checklist_config: {
       service_name: 'DALIA_M11_Final_Demo_Checklist',
       service_version: 'v1',
       environment: 'demo',

       /*
        * Puedes pasar estos IDs desde otro flujo.
        * Si llegan vacíos, el flujo intentará trabajar con lo disponible en el input.
        */
       validation_run_id: input.validation_run_id || '',
       technical_run_id: input.technical_run_id || '',
       narrative_rehearsal_id: input.narrative_rehearsal_id || '',

       go_no_go_policy: {
         minimum_readiness_score: 85,
         allow_go_with_warnings: true,

         critical_e2e_cases: [
           'UC01',
           'UC02',
           'UC03',
           'UC04',
           'UC05'
         ],

         critical_technical_components: [
           'Supabase',
           'M8 Observability',
           'Catalog / Google Sheets',
           'Qdrant',
           'Google Drive',
           'WhatsApp',
         ],

         hard_blockers: [
           'missing_e2e_results',
           'critical_e2e_case_failed',
           'technical_no_go',
           'narrative_no_go',
           'm8_evidence_missing',
           'primary_channel_failed'
         ]
       },

       storage: {
         validation_results_table: 'dalia_demo_validation_results',
         copy_sequence_findings_table: 'dalia_demo_copy_sequence_findings',
         technical_checks_table: 'dalia_demo_technical_rehearsal_checks',
         narrative_rehearsals_table: 'dalia_demo_narrative_rehearsals',
         final_checklists_table: 'dalia_demo_final_checklists'
       }
     }
   }
 }
];

function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

const input = items[0]?.json || {};
const config = input.final_checklist_config || {};

const validationRunId =
 clean(config.validation_run_id) ||
 clean(input.validation_run?.validation_run_id) ||
 clean(input.validation_run_id);

const technicalRunId =
 clean(config.technical_run_id) ||
 clean(input.technical_run?.validation_run_id) ||
 clean(input.technical_run_id) ||
 validationRunId;

const narrativeRehearsalId =
 clean(config.narrative_rehearsal_id) ||
 clean(input.narrative_rehearsal?.narrative_rehearsal_id) ||
 clean(input.narrative_rehearsal_id);

return [
 {
   json: {
     ...input,
     final_validation_context: {
       validation_run_id: validationRunId,
       technical_run_id: technicalRunId,
       narrative_rehearsal_id: narrativeRehearsalId,
       environment: config.environment || 'demo',
       resolved_at: new Date().toISOString()
     }
   }
 }
];

const context = $('Resolve Validation Context').first().json || {};

const rows = items
 .map(item => item.json || {})
 .filter(row => row.case_id);

const expectedCases = ['UC01', 'UC02', 'UC03', 'UC04', 'UC05'];

const foundCases = rows.map(row => row.case_id);
const missingCases = expectedCases.filter(caseId => !foundCases.includes(caseId));

const failedCases = rows.filter(row => row.status === 'failed');
const warningCases = rows.filter(row => row.status === 'warning');
const passedCases = rows.filter(row => row.status === 'passed');

return [
 {
   json: {
     ...context,
     e2e_evidence: {
       rows,
       total_found: rows.length,
       expected_cases: expectedCases,
       found_cases: foundCases,
       missing_cases: missingCases,
       passed_cases: passedCases.length,
       warning_cases: warningCases.length,
       failed_cases: failedCases.length,
       failed_case_ids: failedCases.map(row => row.case_id),
       warning_case_ids: warningCases.map(row => row.case_id),
       complete: missingCases.length === 0,
       status:
         missingCases.length > 0 || failedCases.length > 0
           ? 'failed'
           : warningCases.length > 0
             ? 'warning'
             : 'passed'
     }
   }
 }
];

const context = $('Normalize E2E Validation Evidence').first().json || {};

const rows = items
 .map(item => item.json || {})
 .filter(row => row.case_id);

const failed = rows.filter(row => row.status === 'failed');
const warning = rows.filter(row => row.status === 'warning');
const passed = rows.filter(row => row.status === 'passed');

const adjustmentBacklog = rows.flatMap(row => {
 const backlog = Array.isArray(row.adjustment_backlog)
   ? row.adjustment_backlog
   : [];

 return backlog.map(item => ({
   case_id: row.case_id,
   case_name: row.case_name,
   ...item
 }));
});

return [
 {
   json: {
     ...context,
     copy_sequence_evidence: {
       rows,
       total_found: rows.length,
       passed: passed.length,
       warning: warning.length,
       failed: failed.length,
       failed_case_ids: failed.map(row => row.case_id),
       warning_case_ids: warning.map(row => row.case_id),
       adjustment_backlog: adjustmentBacklog,
       status:
         failed.length > 0
           ? 'failed'
           : warning.length > 0
             ? 'warning'
             : 'passed'
     }
   }
 }
];

const context = $('Normalize Copy Sequence Evidence').first().json || {};
const policy = context.final_checklist_config?.go_no_go_policy || {};

const rows = items
 .map(item => item.json || {})
 .filter(row => row.check_id);

const failed = rows.filter(row => row.status === 'failed');
const warning = rows.filter(row => row.status === 'warning');
const passed = rows.filter(row => row.status === 'passed');

const criticalFailures = failed.filter(row => row.critical === true);

const primaryChannelFailure = failed.some(row =>
 row.component === 'WhatsApp' && row.critical === true
);

const criticalComponents = policy.critical_technical_components || [];

const missingCriticalComponents = criticalComponents.filter(component =>
 !rows.some(row => row.component === component)
);

return [
 {
   json: {
     ...context,
     technical_evidence: {
       rows,
       total_found: rows.length,
       passed: passed.length,
       warning: warning.length,
       failed: failed.length,
       critical_failures: criticalFailures.map(row => ({
         check_id: row.check_id,
         check_name: row.check_name,
         component: row.component
       })),
       missing_critical_components: missingCriticalComponents,
       primary_channel_failure: primaryChannelFailure,
       status:
         criticalFailures.length > 0 || missingCriticalComponents.length > 0
           ? 'failed'
           : warning.length > 0
             ? 'warning'
             : 'passed'
     }
   }
 }
];

const context = $('Normalize Technical Rehearsal Evidence').first().json || {};
const row = items[0]?.json || {};

const hasNarrative = Boolean(row.narrative_rehearsal_id);

const noGo =
 row.go_no_go === 'NO_GO_NARRATIVE' ||
 row.status === 'narrative_not_ready';

const warnings = [];

if (!hasNarrative) {
 warnings.push({
   code: 'missing_narrative_rehearsal',
   detail: 'No se encontró ensayo narrativo/comercial.'
 });
}

if (row.go_no_go === 'GO_NARRATIVE_WITH_WARNINGS') {
 warnings.push({
   code: 'narrative_ready_with_warnings',
   detail: row.findings || []
 });
}

return [
 {
   json: {
     ...context,
     narrative_evidence: {
       row,
       found: hasNarrative,
       status: !hasNarrative
         ? 'warning'
         : noGo
           ? 'failed'
           : row.go_no_go === 'GO_NARRATIVE_WITH_WARNINGS'
             ? 'warning'
             : 'passed',
       go_no_go: row.go_no_go || '',
       rehearsal_status: row.status || '',
       warnings
     }
   }
 }
];

const input = items[0]?.json || {};

const e2e = input.e2e_evidence || {};
const copy = input.copy_sequence_evidence || {};
const technical = input.technical_evidence || {};
const narrative = input.narrative_evidence || {};

function item(id, category, label, status, required, evidence = {}) {
 return {
   item_id: id,
   category,
   label,
   status,
   required,
   evidence
 };
}

const checklistItems = [
 item(
   'FINAL01',
   'end_to_end',
   'Los 5 casos obligatorios fueron ejecutados',
   e2e.complete ? 'passed' : 'failed',
   true,
   {
     found_cases: e2e.found_cases,
     missing_cases: e2e.missing_cases
   }
 ),
 item(
   'FINAL02',
   'end_to_end',
   'No existen casos E2E críticos fallidos',
   e2e.failed_cases > 0 ? 'failed' : e2e.warning_cases > 0 ? 'warning' : 'passed',
   true,
   {
     failed_case_ids: e2e.failed_case_ids,
     warning_case_ids: e2e.warning_case_ids
   }
 ),
 item(
   'FINAL03',
   'visible_experience',
   'Copy y secuencia visible validados',
   copy.status || 'warning',
   true,
   {
     failed_case_ids: copy.failed_case_ids,
     warning_case_ids: copy.warning_case_ids
   }
 ),
 item(
   'FINAL04',
   'technical',
   'Ensayo técnico aprobado',
   technical.status || 'failed',
   true,
   {
     critical_failures: technical.critical_failures,
     missing_critical_components: technical.missing_critical_components
   }
 ),
 item(
   'FINAL05',
   'technical',
   'Canal principal WhatsApp listo',
   technical.primary_channel_failure ? 'failed' : 'passed',
   true,
   {
     primary_channel_failure: technical.primary_channel_failure
   }
 ),
 item(
   'FINAL06',
   'narrative',
   'Ensayo narrativo/comercial preparado',
   narrative.status || 'warning',
   true,
   {
     go_no_go: narrative.go_no_go,
     rehearsal_status: narrative.rehearsal_status
   }
 ),
 item(
   'FINAL07',
   'observability',
   'Existe evidencia de trazabilidad M8',
   e2e.total_found > 0 ? 'passed' : 'failed',
   true,
   {
     e2e_logs_found: e2e.total_found
   }
 ),
 item(
   'FINAL08',
   'fallback',
   'Existe plan de fallback para fallos de demo',
   narrative.row?.fallback_plan && Array.isArray(narrative.row.fallback_plan) && narrative.row.fallback_plan.length > 0
     ? 'passed'
     : 'warning',
   true,
   {
     fallback_items_count: Array.isArray(narrative.row?.fallback_plan)
       ? narrative.row.fallback_plan.length
       : 0
   }
 ),
 item(
   'FINAL09',
   'commercial',
   'La demo tiene guion de apertura, escenas y cierre',
   narrative.row?.demo_script && narrative.row?.demo_scenes
     ? 'passed'
     : 'warning',
   true,
   {
     scenes_count: Array.isArray(narrative.row?.demo_scenes)
       ? narrative.row.demo_scenes.length
       : 0
   }
 ),
 item(
   'FINAL10',
   'support',
   'Backlog de ajustes identificado si hay warnings',
   copy.adjustment_backlog?.length > 0 || narrative.row?.adjustment_backlog?.length > 0
     ? 'warning'
     : 'passed',
   false,
   {
     copy_backlog_count: copy.adjustment_backlog?.length || 0,
     narrative_backlog_count: Array.isArray(narrative.row?.adjustment_backlog)
       ? narrative.row.adjustment_backlog.length
       : 0
   }
 )
];

return [
 {
   json: {
     ...input,
     final_demo_checklist: {
       checklist_items: checklistItems,
       built_at: new Date().toISOString()
     }
   }
 }
];

function makeId(prefix) {
 const ts = Date.now();
 const rand = Math.random().toString(36).slice(2, 8).toUpperCase();
 return `${prefix}_${ts}_${rand}`;
}

const input = items[0]?.json || {};
const context = input.final_validation_context || {};
const checklist = input.final_demo_checklist || {};
const policy = input.final_checklist_config?.go_no_go_policy || {};

const itemsList = checklist.checklist_items || [];

const blockers = [];
const warnings = [];

for (const item of itemsList) {
 if (item.required && item.status === 'failed') {
   blockers.push({
     item_id: item.item_id,
     category: item.category,
     label: item.label,
     evidence: item.evidence
   });
 }

 if (item.status === 'warning') {
   warnings.push({
     item_id: item.item_id,
     category: item.category,
     label: item.label,
     evidence: item.evidence
   });
 }
}

const total = itemsList.length || 1;
const passedWeight = itemsList.filter(i => i.status === 'passed').length;
const warningWeight = itemsList.filter(i => i.status === 'warning').length * 0.5;

const readinessScore = Math.round(((passedWeight + warningWeight) / total) * 100);

let goNoGo = 'NO_GO_DEMO';
let status = 'not_ready';

if (blockers.length === 0 && readinessScore >= Number(policy.minimum_readiness_score || 85)) {
 if (warnings.length > 0 && policy.allow_go_with_warnings) {
   goNoGo = 'GO_WITH_WARNINGS';
   status = 'ready_with_warnings';
 } else {
   goNoGo = 'GO_DEMO';
   status = 'ready';
 }
}

const finalSummary =
 goNoGo === 'GO_DEMO'
   ? `Demo lista. Score ${readinessScore}/100. Sin bloqueadores.`
   : goNoGo === 'GO_WITH_WARNINGS'
     ? `Demo lista con advertencias. Score ${readinessScore}/100. Revisar warnings antes de presentar.`
     : `Demo no lista. Score ${readinessScore}/100. Existen ${blockers.length} bloqueadores.`;

const nextActions = [];

if (blockers.length > 0) {
 nextActions.push({
   priority: 'high',
   action: 'Resolver bloqueadores antes de ejecutar la demo.',
   blockers
 });
}

if (warnings.length > 0) {
 nextActions.push({
   priority: 'medium',
   action: 'Revisar advertencias y preparar explicación o fallback.',
   warnings
 });
}

if (goNoGo !== 'NO_GO_DEMO') {
 nextActions.push({
   priority: 'low',
   action: 'Preparar entorno, abrir canales de prueba, abrir consultas M8 y ejecutar ensayo final corto.'
 });
}

const finalChecklistRecord = {
 final_checklist_id: makeId('finaldemo'),
 validation_run_id: context.validation_run_id || '',
 technical_run_id: context.technical_run_id || '',
 narrative_rehearsal_id: context.narrative_rehearsal_id || '',

 environment: context.environment || 'demo',
 status,
 go_no_go: goNoGo,
 readiness_score: readinessScore,

 checklist_items: itemsList,

 evidence_summary: {
   e2e: input.e2e_evidence || {},
   copy_sequence: input.copy_sequence_evidence || {},
   technical: input.technical_evidence || {},
   narrative: input.narrative_evidence || {}
 },

 blockers,
 warnings,

 fallback_plan: Array.isArray(input.narrative_evidence?.row?.fallback_plan)
   ? input.narrative_evidence.row.fallback_plan
   : [],

 final_summary: finalSummary,
 next_actions: nextActions
};

return [
 {
   json: {
     ...input,
     final_demo_decision: {
       go_no_go: goNoGo,
       status,
       readiness_score: readinessScore,
       blockers,
       warnings,
       final_summary: finalSummary,
       next_actions: nextActions
     },
     final_checklist_record: finalChecklistRecord
   }
 }
];

const input = $('Calculate Go No-Go Decision').first().json || {};
const record = input.final_checklist_record || {};
const decision = input.final_demo_decision || {};

return [
 {
   json: {
     schema_version: 'dalia.m11.final_demo_readiness.v1',
     success: decision.go_no_go !== 'NO_GO_DEMO',
     result_type: 'final_demo_checklist_completed',

     final_checklist: {
       final_checklist_id: record.final_checklist_id || '',
       validation_run_id: record.validation_run_id || '',
       technical_run_id: record.technical_run_id || '',
       narrative_rehearsal_id: record.narrative_rehearsal_id || '',
       status: decision.status || '',
       go_no_go: decision.go_no_go || '',
       readiness_score: decision.readiness_score || 0
     },

     summary: decision.final_summary || '',

     blockers: decision.blockers || [],
     warnings: decision.warnings || [],
     next_actions: decision.next_actions || [],

     checklist_items: record.checklist_items || [],

     completed_at: new Date().toISOString()
   }
 }
];

const input = items[0]?.json || {};

return [
 {
   json: {
     ...input,
     m11_config: {
       service_name: 'DALIA_M11_Demo_Validation_Runner',
       service_version: 'v1',

       environment: 'demo',

       /*
        * Opciones:
        * manual_evidence: tú ejecutas los mensajes por WhatsApp/Telegram y M11 evalúa logs.
        * webhook: M11 intenta enviar los mensajes a un webhook principal de entrada.
        */
       execution_mode: 'manual_evidence',

       /*
        * Si usas modo webhook, reemplaza esta URL.
        */
       main_entry_webhook_url: 'REEMPLAZAR_WEBHOOK_PRINCIPAL_DALIA',

       test_context: {
         business_id: 'business_demo',
         channel: 'wa', // Cambiado a 'wa' para que coincida con tus logs
         bot_id: '1104496126080610', // ¡Nueva variable dinámica agregada!
         user_id: '573108058407', // Tu número real de pruebas
         display_name: 'Tester Demo'
       },

       validation_policy: {
         wait_seconds_after_case: 8,
         evidence_window_minutes: 60,
         fail_on_critical_error_events: true
       },

       storage: {
         validation_runs_table: 'dalia_demo_validation_runs',
         validation_results_table: 'dalia_demo_validation_results',
         observability_events_table: 'dalia_observability_events_lite'
       }
     }
   }
 }
];

function makeId(prefix) {
 const ts = Date.now();
 const rand = Math.random().toString(36).slice(2, 8).toUpperCase();
 return `${prefix}_${ts}_${rand}`;
}

const input = items[0]?.json || {};
const config = input.m11_config || {};

const now = new Date().toISOString();

const validationRun = {
 validation_run_id: makeId('valrun_demo'),
 environment: config.environment || 'demo',
 execution_mode: config.execution_mode || 'manual_evidence',
 status: 'running',

 started_at: now,
 finished_at: null,

 total_cases: 5,
 passed_cases: 0,
 warning_cases: 0,
 failed_cases: 0,

 go_no_go: '',
 summary: '',

 metadata: {
   service_name: config.service_name,
   service_version: config.service_version,
   test_context: config.test_context,
   validation_policy: config.validation_policy,
   created_at: now
 }
};

return [
 {
   json: {
     ...input,
     validation_run: validationRun
   }
 }
];

function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

const base = $('Build Validation Run Draft').first().json || {};
const config = base.m11_config || {};
const run = base.validation_run || {};

const ctx = config.test_context || {};

// 1. Extraemos las variables limpias desde la configuración (cero datos quemados)
const channel = clean(ctx.channel || 'wa');
const userPhone = clean(ctx.user_id || '');
const botId = clean(ctx.bot_id || '');

// 2. Construimos los IDs dinámicamente tal como los guarda tu bot
const userId = `${channel}_demo_${botId}_${userPhone}`;
const conversationId = `conv_${channel}_${botId}_${userPhone}`;
const sessionId = `${channel}_demo_${botId}_${userPhone}`;

const commonTrace = {
 conversation_id: conversationId,
 session_id: sessionId
};

const commonContext = {
 business_id: ctx.business_id || 'business_demo',
 environment: config.environment || 'demo',
 channel,
 user_id: userId,
 display_name: ctx.display_name || 'Tester Demo'
};

const testCases = [
 {
   case_id: 'UC01',
   case_name: 'Entrada simple / saludo controlado',
   case_type: 'conversation_basic',
   critical: true,
   turns: [
     {
       turn: 1,
       text: 'hola'
     }
   ],
   expected_events: [
     'message_received',
     'intent_classified',
     'product_recommended',
     'message_sent'
   ],
   expected_visible: {
     max_messages: 1,
     short_response: false,
     should_not_show_sku: true
   }
 },
 {
   case_id: 'UC02',
   case_name: 'Búsqueda y recomendación de producto',
   case_type: 'product_search',
   critical: true,
   turns: [
     {
       turn: 1,
       text: 'busco un cepillo de dientes ecológico'
     }
   ],
   expected_events: [
     'message_received',
     'intent_classified',
     // ¡Adiós response_generated fantasma!
     'product_recommended',
     'message_sent'
   ],
   expected_visible: {
     should_recommend_catalog_products: true,
     max_options: 5,
     should_not_show_sku: true,
     should_not_invent_price: true,
     should_not_invent_stock: true
   }
 },
 {
   case_id: 'UC03',
   case_name: 'Producto concreto con imagen real',
   case_type: 'product_image',
   critical: true,
   turns: [
     {
       turn: 1,
       text: 'quiero ver el termo de bambú'
     }
   ],
   expected_events: [
     'message_received',
     'intent_classified',
     // ¡Adiós response_generated fantasma!
     'message_sent',
     'image_sent'
   ],
   expected_visible: {
     image_required: true,
     fallback_allowed: false,
     should_not_show_sku: true
   }
 },
 {
   case_id: 'UC04',
   case_name: 'Comercio Accional Lite de punta a punta',
   case_type: 'commerce_lite',
   critical: true,
   turns: [
     {
       turn: 1,
       text: 'lo llevo'
     },
     {
       turn: 2,
       text: 'Me llamo Em, estoy en Bogotá y la entrega sería en la Calle 123'
     },
     {
       turn: 3,
       text: 'continuar'
     },
     {
       turn: 4,
       text: 'continuar con el pago demo'
     },
     {
       turn: 5,
       text: 'ya pagué'
     },
     {
       turn: 6,
       text: 'continuar con el envío'
     }
   ],
   expected_events: [
     'message_received',
     'intent_classified',
     'message_sent'
   ],
   expected_visible: {
     should_create_transaction: true,
     should_capture_minimum_data: true,
     should_simulate_payment: true,
     should_confirm_demo_order: true,
     should_create_fake_tracking: true,
     should_clarify_demo_not_real_payment: true
   }
 },
 {
   case_id: 'UC05',
   case_name: 'Handoff humano básico',
   case_type: 'handoff_lite',
   critical: true,
   turns: [
     {
       turn: 1,
       text: 'quiero hablar con un asesor'
     }
   ],
   expected_events: [
     'message_received',
     'intent_classified',
     'handoff_triggered',
     'handoff_human_notified',
     'message_sent'
   ],
   expected_visible: {
     should_create_handoff: true,
     should_notify_customer: true,
     should_notify_human_channel: true,
     should_not_use_technical_terms: true
   }
 }
];

return testCases.map(testCase => ({
 json: {
   validation_run: run,
   m11_config: config,
   test_case: {
     ...testCase,
     trace: commonTrace,
     context: commonContext,
     expected_correlation: {
       conversation_id: conversationId,
       session_id: sessionId,
       user_id: userId
     }
   }
 }
}));

const input = items[0]?.json || {};

const testCase = input.test_case || {};
const config = input.m11_config || {};

const executionMode = config.execution_mode || 'manual_evidence';

const executionPayload = {
 schema_version: 'dalia.m11.test_case_execution.v1',
 execution_mode: executionMode,

 test_case_id: testCase.case_id,
 test_case_name: testCase.case_name,
 case_type: testCase.case_type,

 trace: testCase.trace || {},
 context: testCase.context || {},

 turns: testCase.turns || [],

 expected_events: testCase.expected_events || [],
