 });
}

if (includesAny(allText, forbiddenTerms)) {
 findings.push({
   severity: 'failed',
   code: 'internal_or_technical_terms_visible',
   detail: 'El copy visible contiene términos técnicos o internos.'
 });
}

if (hasSkuLikePattern(allText)) {
 findings.push({
   severity: 'failed',
   code: 'sku_visible_to_customer',
   detail: 'El texto visible parece exponer SKU o códigos internos.'
