function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function asArray(value) {
 return Array.isArray(value) ? value : [];
}

function safePayload(row) {
 const payload = row.payload || {};
 if (typeof payload === 'object') return payload;

 try {
   return JSON.parse(payload);
 } catch (e) {
   return {};
 }
}

function getTextPreview(row) {
 const payload = safePayload(row);

 return clean(
   payload.visible_text_preview ||
   payload.replyText ||
   payload.reply_text ||
   payload.message_text ||
   payload.text ||
   payload.customer_notification_text ||
   ''
 );
}

function inferVisibleUnit(row) {
 const payload = safePayload(row);

 if (row.event_name === 'image_sent') {
   return {
     type: 'image',
     event_id: row.event_id,
     timestamp: row.timestamp,
     module: row.module,
     status: row.status,
     source: payload.image_source || payload.source || ''
   };
 }

 if (row.event_name === 'message_sent') {
   const units = asArray(payload.visible_units);

   if (units.length > 0) {
     return units.map(unit => ({
       type: clean(unit.type || 'text'),
       event_id: row.event_id,
       timestamp: row.timestamp,
       module: row.module,
       status: row.status
     }));
   }

   if (payload.image_sent && payload.text_sent) {
     return [
       {
         type: 'text',
         event_id: row.event_id,
         timestamp: row.timestamp,
         module: row.module,
         status: row.status
       },
       {
         type: 'image',
         event_id: row.event_id,
         timestamp: row.timestamp,
         module: row.module,
         status: row.status
       }
     ];
   }

   if (payload.image_sent) {
     return {
       type: 'image',
       event_id: row.event_id,
       timestamp: row.timestamp,
       module: row.module,
       status: row.status
     };
   }

   return {
     type: 'text',
     event_id: row.event_id,
     timestamp: row.timestamp,
     module: row.module,
     status: row.status
   };
 }

 if (row.event_name === 'response_generated') {
   return {
     type: 'generated_response',
     event_id: row.event_id,
     timestamp: row.timestamp,
     module: row.module,
     status: row.status
   };
 }

 return null;
}

