const sequenceReview = input.sequence_review || {};

const allFindings = [
 ...(copyReview.findings || []),
 ...(copyReview.warnings || []).map(w => ({ severity: 'warning', ...w })),
 ...(sequenceReview.findings || []),
 ...(sequenceReview.warnings || []).map(w => ({ severity: 'warning', ...w }))
];

const backlog = [];

for (const finding of allFindings) {
 const code = finding.code || '';

 if (code.includes('sku_visible')) {
   backlog.push({
     target_module: 'M3/M7',
     priority: 'high',
     action: 'Ajustar post-procesamiento para eliminar SKU o códigos internos del texto visible.',
